-- =====================================================================
-- IMPORT FRA FIXIT-RAPPORTEN «GJENBESØK» (#201, 01.03.2013 – 30.09.2026)
--
--   1) KUNDEKLUBB: Fixit-besøk teller med i kundens nivå (Bronse/Sølv/Gull).
--      Ny kolonne customers.legacy_visits = antall besøk i Fixit (minimum),
--      og nivået regnes nå av  fullførte bookinger + legacy_visits.
--      Klippekortet (10 klipp = gratis) påvirkes IKKE – det starter på 0.
--
--   2) KUNDE ↔ BARBER: hvilke barbere kunden har klippet hos i Fixit
--      (brukes av «Klippet av barber» i kundefilteret og markedsføringen).
--
--   Rapporten har bare NAVN (ingen telefon/e-post) og bare kunder som kom
--   tilbake innen 90 dager. Derfor er importen forsiktig:
--     * En kunde kobles bare når navnet matcher NØYAKTIG ÉN kunde i systemet
--       (store/små bokstaver og doble mellomrom ignoreres).
--     * Besøk = gjenbesøk + 1 per barber (minst så mange), summert over alle
--       barbere – også de som har sluttet og «Anonymisert».
--     * Har kunden allerede besøkstall fra Fixit-kundelistene (Vani/Soren),
--       brukes det høyeste tallet. Ingenting telles dobbelt.
--     * En barber kobles bare når navnet matcher en ansatt (fullt navn, eller
--       fornavn når bare én ansatt har det fornavnet). Eksisterende
--       koblinger (Vani/Soren) røres ikke.
--
--   Trygt å kjøre flere ganger. Viser en oppsummering til slutt.
-- =====================================================================
drop table if exists gb_raw, gb_staff, gb_cust, gb_visits;

begin;

-- ---------- 1a) Kolonne for Fixit-besøk ----------
alter table customers add column if not exists legacy_visits int not null default 0;

-- ---------- Rådata fra rapporten (barber, kunde, gjenbesøk innen 90 dager) ----------
create temp table gb_raw (barber text, customer text, returns int);

