-- ---------- Kunde-kobling (bare entydige navn) ----------
create temp table gb_cust as
with norm as (
  select id, lower(regexp_replace(trim(full_name), '\s+', ' ', 'g')) as n from customers
),
uniq as (select n, min(id::text)::uuid as id from norm group by n having count(*) = 1)
select distinct r.customer, u.id as customer_id
  from gb_raw r
  join uniq u on u.n = lower(regexp_replace(trim(r.customer), '\s+', ' ', 'g'));

-- ---------- 1b) Fixit-besøk per kunde ----------
create temp table gb_visits as
select c.customer_id, sum(r.returns + 1)::int as visits
  from gb_raw r
  join gb_cust c on c.customer = r.customer
 group by c.customer_id;

update customers cu
   set legacy_visits = greatest(
         coalesce(v.visits, 0),
         coalesce((select sum(cb.visits) from customer_barbers cb
                    where cb.customer_id = cu.id and cb.source = 'fixit'), 0)
       )
  from gb_visits v
 where v.customer_id = cu.id;

-- Kunder som bare finnes i Fixit-kundelistene (Vani/Soren), ikke i rapporten.
update customers cu
   set legacy_visits = x.visits
  from (select customer_id, sum(visits)::int as visits
          from customer_barbers where source = 'fixit'
         group by customer_id) x
 where x.customer_id = cu.id
   and cu.legacy_visits < x.visits;

-- ---------- 1c) Kundeklubb-nivå: fullførte bookinger + Fixit-besøk ----------
create or replace function customer_membership(p_customer uuid)
returns table(
  tier_id        smallint,
  tier_name      text,
  benefit        text,
  color          text,
  spend          numeric,
  visits         int,
  next_tier_name text,
  next_min_spend numeric,
  next_min_visits int
)
language plpgsql stable security definer set search_path = public as $$
declare
  v_spend  numeric;
  v_visits int;
  v_tier   membership_tiers;
  v_next   membership_tiers;
begin
  select coalesce(sum(total_nok), 0) into v_spend
    from sales where customer_id = p_customer;
  select count(*) into v_visits
    from bookings where customer_id = p_customer and status = 'completed';
  -- Besøk fra Fixit (før det nye systemet) teller også.
  v_visits := coalesce(v_visits, 0)
            + coalesce((select legacy_visits from customers where id = p_customer), 0);

  select * into v_tier
    from membership_tiers
   where v_spend >= min_spend or v_visits >= min_visits
   order by sort_order desc, id desc
   limit 1;

  if v_tier.id is null then
    select * into v_tier from membership_tiers order by sort_order asc, id asc limit 1;
  end if;

  select * into v_next
    from membership_tiers
   where sort_order > v_tier.sort_order
   order by sort_order asc, id asc
   limit 1;

  return query select
    v_tier.id, v_tier.name, v_tier.benefit, v_tier.color,
    v_spend, coalesce(v_visits, 0),
    v_next.name, v_next.min_spend, v_next.min_visits;
end $$;

revoke execute on function customer_membership(uuid) from public, anon;
grant  execute on function customer_membership(uuid) to authenticated;

-- ---------- 2) Kunde ↔ barber ----------
create temp table gb_staff as
with b as (select distinct barber from gb_raw),
st as (
  select id, lower(trim(full_name)) as full_l,
         lower(split_part(trim(full_name), ' ', 1)) as first_l
    from staff
),
first_unique as (
  select first_l from st group by first_l having count(*) = 1
)
select b.barber,
       coalesce(
         (select st.id from st where st.full_l = lower(trim(b.barber)) limit 1),
         (select st.id from st join first_unique fu on fu.first_l = st.first_l
           where st.first_l = lower(split_part(trim(b.barber), ' ', 1)) limit 1)
       ) as staff_id
  from b;

insert into customer_barbers (customer_id, staff_id, visits, source)
select c.customer_id, s.staff_id, max(r.returns) + 1, 'fixit-gjenbesok'
  from gb_raw r
  join gb_staff s on s.barber = r.barber and s.staff_id is not null
  join gb_cust  c on c.customer = r.customer
 group by c.customer_id, s.staff_id
on conflict (customer_id, staff_id) do nothing;

commit;

notify pgrst, 'reload schema';

-- ---------- Oppsummering ----------
-- Øverst: totalen. Deretter per barber i Fixit: hvem den ble koblet til i
-- systemet (tom = barberen finnes ikke / har sluttet) og hvor mange kunder
-- som ble funnet.
select 'TOTALT' as barber_i_fixit,
       null::text as ansatt_i_systemet,
       (select count(distinct customer) from gb_raw)::bigint as kunder_i_rapporten,
       (select count(*) from gb_cust)::bigint                 as kunder_funnet,
       (select count(*) from customers where legacy_visits > 0)::bigint as kunder_med_fixit_besok
union all
select * from (
  select r.barber,
         st.full_name,
         count(*)::bigint,
         count(c.customer_id)::bigint,
         null::bigint
    from gb_raw r
    left join gb_staff s on s.barber = r.barber
    left join staff st on st.id = s.staff_id
    left join gb_cust c on c.customer = r.customer
   group by r.barber, st.full_name
   order by count(*) desc
) t;
